  1→"use client";
  2→
  3→/**
  4→ * Main chat interface for the thos dashboard.
  5→ *
  6→ * Composes {@link StatusBar}, a scrollable message list ({@link Message}
  7→ * and {@link ControlRequest} cards), and an input bar. The submit button
  8→ * text toggles between "Spawn" (when idle/done) and "Send" (when an
  9→ * agent session is active). Auto-scrolls on new messages.
 10→ *
 11→ * A toggle in the top-right switches between the processed chat view
 12→ * and a raw JSON view of all Claude NDJSON messages.
 13→ *
 14→ * Receives all data and callbacks via props — the parent page component
 15→ * owns the WebSocket hook and orchestrates multiple agents.
 16→ */
 17→
 18→import { useEffect, useMemo, useRef, useState } from "react";
 19→import type { AgentStatus, ChatMessage, ClaudeMessage } from "@/lib/types";
 20→import { condenseMessages } from "@/lib/condense-messages";
 21→import { StatusBar } from "./status-bar";
 22→import { Message } from "./message";
 23→import { ControlRequest } from "./control-request";
 24→import { UserQuestion } from "./user-question";
 25→import { CondensedToolGroup } from "./condensed-tool-group";
 26→import { Button } from "@/components/ui/button";
 27→
 28→export function Chat({
 29→  connected,
 30→  loading,
 31→  status,
 32→  messages,
 33→  rawMessages,
 34→  onSendMessage,
 35→  onSpawnAgent,
 36→  onRespondToControl,
 37→  onRespondToUserQuestion,
 38→  showTasks,
 39→  onToggleTasks,
 40→  onToggleSidebar,
 41→}: {
 42→  connected: boolean;
 43→  loading?: boolean;
 44→  status: AgentStatus;
 45→  messages: ChatMessage[];
 46→  rawMessages: ClaudeMessage[];
 47→  onSendMessage: (content: string) => void;
 48→  onSpawnAgent: (prompt: string) => void;
 49→  onRespondToControl: (requestId: string, allow: boolean) => void;
 50→  onRespondToUserQuestion: (requestId: string, answers: Record<string, string>) => void;
 51→  showTasks?: boolean;
 52→  onToggleTasks?: () => void;
 53→  onToggleSidebar?: () => void;
 54→}) {
 55→  const [input, setInput] = useState("");
 56→  const [showRaw, setShowRaw] = useState(false);
 57→  const scrollRef = useRef<HTMLDivElement>(null);
 58→
 59→  useEffect(() => {
 60→    scrollRef.current?.scrollTo({
 61→      top: scrollRef.current.scrollHeight,
 62→      behavior: "smooth",
 63→    });
 64→  }, [messages, rawMessages, showRaw]);
 65→
 66→  const displayItems = useMemo(() => condenseMessages(messages), [messages]);
 67→  const isActive = status === "connected" || status === "thinking";
 68→  const isArchived = status === "done" || status === "disconnected" || status === "error";
 69→
 70→  function handleSubmit(e: React.FormEvent) {
 71→    e.preventDefault();
 72→    const trimmed = input.trim();
 73→    if (!trimmed) return;
 74→
 75→    if (isActive) {
 76→      onSendMessage(trimmed);
 77→    } else {
 78→      onSpawnAgent(trimmed);
 79→    }
 80→    setInput("");
 81→  }
 82→
 83→  return (
 84→    <div className="flex h-full flex-col">
 85→      <StatusBar
 86→        connected={connected}
 87→        status={status}
 88→        showRaw={showRaw}
 89→        onToggleRaw={() => setShowRaw((v) => !v)}
 90→        showTasks={showTasks}
 91→        onToggleTasks={onToggleTasks}
 92→        onToggleSidebar={onToggleSidebar}
 93→      />
 94→
 95→      <div ref={scrollRef} className="flex-1 overflow-y-auto p-2 md:p-4 space-y-2">
 96→        {loading ? (
 97→          <div className="flex h-full flex-col items-center justify-center gap-3">
 98→            <div className="flex gap-1">
 99→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse" />
100→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse [animation-delay:150ms]" />
101→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse [animation-delay:300ms]" />
102→            </div>
103→            <span className="text-xs text-muted-foreground">
104→              {connected ? "Loading messages..." : "Connecting..."}
105→            </span>
106→          </div>
107→        ) : showRaw ? (
108→          rawMessages.length === 0 ? (
109→            <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
110→              No raw messages yet
111→            </div>
112→          ) : (
113→            <div className="space-y-1">
114→              {rawMessages.map((msg, i) => (
115→                <RawMessage key={i} message={msg} index={i} />
116→              ))}
117→            </div>
118→          )
119→        ) : (
120→          <>
121→            {messages.length === 0 && (
122→              <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
123→                Type a prompt to spawn a Claude agent
124→              </div>
125→            )}
126→            {displayItems.map((item) => {
127→              if (item.kind === "condensed") {
128→                return <CondensedToolGroup key={item.id} group={item} />;
129→              }
130→              const msg = item.message;
131→              return msg.userQuestion ? (
132→                <UserQuestion
133→                  key={msg.id}
134→                  message={msg}
135→                  onRespond={onRespondToUserQuestion}
136→                />
137→              ) : msg.controlRequest ? (
138→                <ControlRequest
139→                  key={msg.id}
140→                  message={msg}
141→                  onRespond={onRespondToControl}
142→                />
143→              ) : (
144→                <Message key={msg.id} message={msg} />
145→              );
146→            })}
147→          </>
148→        )}
149→      </div>
150→
151→      {isArchived && messages.length > 0 ? (
152→        <div className="border-t px-4 py-2 text-center text-xs text-muted-foreground">
153→          This session has ended
154→        </div>
155→      ) : (
156→        <form
157→          onSubmit={handleSubmit}
158→          className="flex gap-2 border-t px-2 py-2 md:px-4 md:py-3"
159→        >
160→          <input
161→            type="text"
162→            value={input}
163→            onChange={(e) => setInput(e.target.value)}
164→            placeholder={isActive ? "Send a follow-up..." : "Enter a prompt to spawn agent..."}
165→            className="flex-1 rounded-md border bg-background px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-ring"
166→          />
167→          <Button type="submit" disabled={!connected || !input.trim()}>
168→            {isActive ? "Send" : "Spawn"}
169→          </Button>
170→        </form>
171→      )}
172→    </div>
173→  );
174→}
